#!/usr/bin/env node
'use strict';
// Fixture generator (tests/site-template.cjs): writes figures/dg-stack.html, a shape (b) inline-SVG diagram.
// page.json declares it under "generators"; build-pages --check reruns it in a scratch copy and compares.
const fs = require('fs');
const path = require('path');
const text = (x, y, key) => `<text x="${x}" y="${y}" text-anchor="middle" font-size="12" data-i18n="dg.stack.${key}"></text>`;
const svg = `<svg viewBox="0 0 200 80" role="img" data-i18n-aria="dg.stack.aria"><rect x="10" y="10" width="180" height="24"/>${text(100, 27, 'top')}<rect x="10" y="46" width="180" height="24"/>${text(100, 63, 'bottom')}</svg>`;
const html = `<!-- GENERATED by tools/gen.cjs (page.json generators); edit the generator and rerun it, do not edit this file. -->\n` +
  `<figure class="dia" id="dg-stack">${svg}<figcaption data-i18n-html="dg.stack.cap"></figcaption></figure>\n`;
fs.writeFileSync(path.join(__dirname, '..', 'figures', 'dg-stack.html'), html);
